import bpy

def make_materials(root):
 def base(name,col,metal=0,rough=.75):
  m=bpy.data.materials.new(name);m.use_nodes=True;m.diffuse_color=(*col,1);n=m.node_tree.nodes;l=m.node_tree.links;p=n.get('Principled BSDF');p.inputs['Base Color'].default_value=(*col,1);p.inputs['Metallic'].default_value=metal;p.inputs['Roughness'].default_value=rough;return m,n,l,p
 def noise(n,scale,detail=3):
  a=n.new('ShaderNodeTexNoise');a.inputs['Scale'].default_value=scale;a.inputs['Detail'].default_value=detail;a.inputs['Roughness'].default_value=.72;return a
 def ramp(n,colors,positions=None,mode='LINEAR'):
  a=n.new('ShaderNodeValToRGB');a.color_ramp.interpolation=mode
  for i,col in enumerate(colors):
   e=a.color_ramp.elements[i] if i<2 else a.color_ramp.elements.new(positions[i]);e.position=positions[i] if positions else i;e.color=(*col,1)
  return a
 def vector(n,obj=None):
  a=n.new('ShaderNodeTexCoord');a.object=obj;return a.outputs['Object']
 def bump(n,l,src,p,strength=.25,distance=.01):
  a=n.new('ShaderNodeBump');a.inputs['Strength'].default_value=strength;a.inputs['Distance'].default_value=distance;l.new(src,a.inputs['Height']);l.new(a.outputs[0],p.inputs['Normal'])
 M={}
 m,n,l,p=base('FINAL / worn multi-tone armor',(.12,.15,.105),.5,.65);v=vector(n,root);a=noise(n,1.1,2);l.new(v,a.inputs[0]);cr=ramp(n,[(.07,.085,.063),(.19,.20,.14),(.31,.29,.21)],[.25,.5,.72],'CONSTANT');l.new(a.outputs[0],cr.inputs[0]);fine=noise(n,145,2);l.new(v,fine.inputs[0]);bump(n,l,fine.outputs[0],p,.16,.0025);r=ramp(n,[(.44,.44,.44),(.8,.8,.8)]);l.new(fine.outputs[0],r.inputs[0]);l.new(r.outputs[0],p.inputs['Roughness'])
 a=noise(n,3.5,4);l.new(v,a.inputs[0]);g=ramp(n,[(.42,.40,.34),(1.05,1.02,.95)]);l.new(a.outputs[0],g.inputs[0]);mix=n.new('ShaderNodeMixRGB');mix.blend_type='MULTIPLY';mix.inputs[0].default_value=.55;l.new(cr.outputs[0],mix.inputs[1]);l.new(g.outputs[0],mix.inputs[2]);sep=n.new('ShaderNodeSeparateXYZ');l.new(v,sep.inputs[0]);h=n.new('ShaderNodeMapRange');h.inputs['From Min'].default_value=.3;h.inputs['From Max'].default_value=1.65;h.inputs['To Min'].default_value=.6;h.inputs['To Max'].default_value=0;l.new(sep.outputs['Z'],h.inputs[0]);mu=n.new('ShaderNodeMath');mu.operation='MULTIPLY';l.new(h.outputs[0],mu.inputs[0]);l.new(a.outputs[0],mu.inputs[1]);d=n.new('ShaderNodeMixRGB');l.new(mu.outputs[0],d.inputs[0]);l.new(mix.outputs[0],d.inputs[1]);d.inputs[2].default_value=(.10,.068,.034,1);l.new(d.outputs[0],p.inputs['Base Color']);M['armor']=m
 for key,name,col,metal,rough,sc,st,dist in [('edge','exposed armor edge',(.14,.16,.115),.72,.38,110,.12,.002),('metal','oiled steel',(.045,.049,.045),.82,.39,90,.22,.003),('rubber','wheel tire rubber',(.013,.016,.012),0,.81,90,.35,.002),('mud','dried earth deposits',(.105,.073,.04),0,.95,45,.45,.012),('concrete','broken aggregate concrete',(.25,.25,.225),0,.92,13,.45,.027),('sand','sandbag canvas',(.29,.235,.15),0,.95,90,.35,.004)]:
  m,n,l,p=base('FINAL / '+name,col,metal,rough);a=noise(n,sc);l.new(vector(n,root if key in ['edge','metal','rubber','mud'] else None),a.inputs[0]);bump(n,l,a.outputs[0],p,st,dist)
  if key=='concrete':r=ramp(n,[(.105,.10,.087),(.41,.40,.35)],[.18,.83]);l.new(a.outputs[0],r.inputs[0]);l.new(r.outputs[0],p.inputs['Base Color'])
  M[key]=m
 M['glass']=base('FINAL / optical glass',(.015,.045,.063),.55,.16)[0];M['dark']=base('FINAL / scorched interior',(.019,.018,.015),0,.96)[0]
 m,n,l,p=base('FINAL / scarred plaster and masonry',(.24,.22,.185),0,.93);v=vector(n);a=noise(n,.8,4);l.new(v,a.inputs[0]);r=ramp(n,[(.065,.064,.057),(.29,.285,.25)],[.23,.8]);l.new(a.outputs[0],r.inputs[0]);sep=n.new('ShaderNodeSeparateXYZ');l.new(v,sep.inputs[0]);geo=n.new('ShaderNodeNewGeometry');normal=n.new('ShaderNodeSeparateXYZ');l.new(geo.outputs['Normal'],normal.inputs[0]);ab=n.new('ShaderNodeMath');ab.operation='ABSOLUTE';l.new(normal.outputs['X'],ab.inputs[0]);mix=n.new('ShaderNodeMixRGB');l.new(ab.outputs[0],mix.inputs[0]);l.new(sep.outputs['X'],mix.inputs[1]);l.new(sep.outputs['Y'],mix.inputs[2]);comb=n.new('ShaderNodeCombineXYZ');l.new(mix.outputs[0],comb.inputs['X']);l.new(sep.outputs['Z'],comb.inputs['Y']);br=n.new('ShaderNodeTexBrick');br.inputs['Scale'].default_value=1;br.inputs['Mortar Size'].default_value=.013;br.inputs['Brick Width'].default_value=.46;br.inputs['Row Height'].default_value=.20;br.inputs['Color1'].default_value=(.25,.125,.07,1);br.inputs['Color2'].default_value=(.13,.075,.045,1);br.inputs['Mortar'].default_value=(.09,.087,.076,1);l.new(comb.outputs[0],br.inputs[0]);mask=ramp(n,[(0,0,0),(1,1,1)],[.62,.76]);l.new(a.outputs[0],mask.inputs[0]);mix=n.new('ShaderNodeMixRGB');l.new(mask.outputs[0],mix.inputs[0]);l.new(r.outputs[0],mix.inputs[1]);l.new(br.outputs['Color'],mix.inputs[2]);l.new(mix.outputs[0],p.inputs['Base Color']);fine=noise(n,38);l.new(v,fine.inputs[0]);bump(n,l,fine.outputs[0],p,.5,.032);M['wall']=m
 m,n,l,p=base('FINAL / rain-wet cracked asphalt',(.04,.043,.04),0,.65);p.inputs['Specular IOR Level'].default_value=.28;v=vector(n);a=noise(n,.7);l.new(v,a.inputs[0]);r=ramp(n,[(.027,.030,.028),(.048,.049,.043)],[.28,.73]);l.new(a.outputs[0],r.inputs[0]);rr=ramp(n,[(.42,.42,.42),(.93,.93,.93)],[.36,.55]);l.new(a.outputs[0],rr.inputs[0]);l.new(rr.outputs[0],p.inputs['Roughness']);fine=noise(n,130,2);l.new(v,fine.inputs[0]);bump(n,l,fine.outputs[0],p,.33,.007)
 vor=n.new('ShaderNodeTexVoronoi');vor.feature='DISTANCE_TO_EDGE';vor.inputs['Scale'].default_value=.75;l.new(v,vor.inputs[0]);th=n.new('ShaderNodeMath');th.operation='LESS_THAN';th.inputs[1].default_value=.004;l.new(vor.outputs['Distance'],th.inputs[0]);mask=noise(n,2.6,2);l.new(v,mask.inputs[0]);gate=n.new('ShaderNodeMath');gate.operation='GREATER_THAN';gate.inputs[1].default_value=.56;l.new(mask.outputs[0],gate.inputs[0]);mu=n.new('ShaderNodeMath');mu.operation='MULTIPLY';l.new(th.outputs[0],mu.inputs[0]);l.new(gate.outputs[0],mu.inputs[1]);mix=n.new('ShaderNodeMixRGB');l.new(mu.outputs[0],mix.inputs[0]);l.new(r.outputs[0],mix.inputs[1]);mix.inputs[2].default_value=(.004,.005,.004,1);l.new(mix.outputs[0],p.inputs['Base Color']);M['road']=m
 def volume(name,col,density,fire=False):
  m=bpy.data.materials.new(name);m.use_nodes=True;n=m.node_tree.nodes;n.clear();l=m.node_tree.links;o=n.new('ShaderNodeOutputMaterial');p=n.new('ShaderNodeVolumePrincipled');p.inputs['Color'].default_value=(*col,1);p.inputs['Anisotropy'].default_value=.15;a=noise(n,3.8,4);tc=n.new('ShaderNodeTexCoord');l.new(tc.outputs['Generated'],a.inputs[0]);r=ramp(n,[(0,0,0),(density,density,density)],[.30,.68]);l.new(a.outputs[0],r.inputs[0]);l.new(r.outputs[0],p.inputs['Density'])
  if fire:
   cr=ramp(n,[(.75,.035,.003),(1,.20,.008),(1,.65,.12)],[.22,.53,.78]);l.new(a.outputs[0],cr.inputs[0]);l.new(cr.outputs[0],p.inputs['Emission Color']);heat=ramp(n,[(0,0,0),(1,1,1)],[.42,.74]);l.new(a.outputs[0],heat.inputs[0]);mu=n.new('ShaderNodeMath');mu.operation='MULTIPLY';mu.inputs[1].default_value=2;l.new(heat.outputs[0],mu.inputs[0]);l.new(mu.outputs[0],p.inputs['Emission Strength'])
  l.new(p.outputs[0],o.inputs['Volume']);return m
 M['smoke']=volume('FINAL / turbulent charcoal smoke',(.12,.11,.095),3.5);M['dust']=volume('FINAL / low drifting dust',(.38,.32,.24),1.1);M['fire']=volume('FINAL / luminous turbulent fire',(.18,.085,.015),.75,True)
 return M
